import io
import torch
import zlib
import base64

BRAIN_PAYLOAD = ""

try:
    compressed_bytes = base64.b64decode(BRAIN_PAYLOAD)
    raw_bytes = zlib.decompress(compressed_bytes)
    buffer = io.BytesIO(raw_bytes)
    state_dict = torch.load(buffer, map_location='cpu', weights_only=True)
    float_dict = {k: v.float() for k, v in state_dict.items()}
    print(float_dict)
    print("✅ Neural Core successfully loaded from payload.")
except Exception as e:
    print(f"❌ Failed to load brain payload: {e}")